"""Qualify exact H2D statistics reuse and live Tensor closure length reads."""

import ast
from collections import Counter, deque
from dataclasses import asdict
from datetime import datetime
import hashlib
import json
from pathlib import Path
from statistics import mean, median
import subprocess
import sys
import time
from types import ModuleType
from unittest.mock import patch

ROOT = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
sys.path.insert(0, str(ROOT))

import torch
from beliefkv.runtime import native_transfer_service as service
from beliefkv.runtime import sglang_v0520_observer as observer
from beliefkv.runtime.sglang_v0520_runtime import NativeAdmissionRuntime
from scripts.benchmark_native_transfer_estimate_cpu import recorded_histories
from scripts.benchmark_checkpoint_ancestry_cpu import fixture

REVISION = "4e16b50"
OUTPUT = ROOT / "experiments/reports/v202_h2d_estimate_tensor_closure_cpu_20261013.json"
TRANSFER = Path("/home/longhao/experiment/BeliefKV/experiments/raw/qwen35_native_predictive_replenished_108plus48_20261013_v42/predictive_h2d/server/transfer_telemetry.jsonl")
if OUTPUT.exists():
    raise ValueError("preserve the previous CPU comparison")
started = datetime.now().astimezone().isoformat()
observer_source = subprocess.check_output([
    "git", "show", f"{REVISION}:beliefkv/runtime/sglang_v0520_observer.py",
], cwd=ROOT, text=True)
baseline = ModuleType("beliefkv.runtime._v202_baseline_observer")
sys.modules[baseline.__name__] = baseline
exec(compile(observer_source, baseline.__name__, "exec"), vars(baseline))


def distribution(values):
    return {"samples": len(values), "mean_us": mean(values), "p50_us": median(values)}


def baseline_estimate(runtime, size, shape):
    return service.estimate_native_service(
        runtime._native_service_samples, size, shape=shape,
    ) or service.estimate_native_service(runtime._h2d_samples, size)


def runtime_fixture(samples):
    runtime = NativeAdmissionRuntime.__new__(NativeAdmissionRuntime)
    runtime._native_service_samples = deque(samples, maxlen=256)
    runtime._h2d_samples = deque(
        ((row.size_bytes, row.submit_to_ack_ms) for row in samples if row.direction == "h2d"),
        maxlen=64,
    )
    runtime._h2d_service_estimates = {}
    runtime.counts = Counter()
    return runtime


histories, evidence = recorded_histories(TRANSFER)
estimate_cases = []
for snapshot, samples in histories:
    for shape in ("full", "mamba", "hybrid"):
        for size in (1_000_000, 32_000_000, 128_000_000, 8_000_000_000):
            for repeat in (1, 4, 16):
                variants = {
                    "baseline": lambda runtime: baseline_estimate(runtime, size, shape),
                    "optimized": lambda runtime: runtime._estimate_h2d_service(size, shape=shape),
                }
                runtimes = {name: runtime_fixture(samples) for name in variants}
                costs = {name: {"wall": [], "thread_cpu": []} for name in variants}
                expected = baseline_estimate(runtimes["baseline"], size, shape)
                for iteration in range(65):
                    order = list(variants)
                    if iteration % 2:
                        order.reverse()
                    for name in order:
                        runtime = runtimes[name]
                        runtime._h2d_service_estimates.clear()
                        wall, cpu = time.perf_counter_ns(), time.thread_time_ns()
                        for _ in range(repeat):
                            result = variants[name](runtime)
                        cpu_us = (time.thread_time_ns() - cpu) / 1000. / repeat
                        wall_us = (time.perf_counter_ns() - wall) / 1000. / repeat
                        if result != expected:
                            raise ValueError("H2D support or statistics changed")
                        if iteration >= 5:
                            costs[name]["wall"].append(wall_us)
                            costs[name]["thread_cpu"].append(cpu_us)
                estimate_cases.append({
                    "snapshot": snapshot, "history_samples": len(samples),
                    "shape": shape, "size_bytes": size, "queries_per_unchanged_history": repeat,
                    "cold_query_included": True, "estimates_equal": True,
                    "estimate": asdict(expected) if expected else None,
                    "costs": {
                        name: {clock: distribution(values) for clock, values in clocks.items()}
                        for name, clocks in costs.items()
                    },
                })
closure_cases = []
for kind in ("cpu_int64_tensor", "range"):
    for mode in ("prepare", "h2d"):
        for depth in (8, 64, 512):
            cache, anchors = fixture({
                "mode": mode, "depth": depth, "leaves": 1, "output_tail_nodes": 0,
            })
            leaf = dict(anchors.component_leaves)[0][0][0]
            node = cache.tree_core.node_by_id(leaf)
            while node is not None:
                full = node.component_data[0]
                if kind == "cpu_int64_tensor":
                    if full.value is not None:
                        full.value = torch.tensor(tuple(full.value), dtype=torch.int64)
                    if full.host_value is not None:
                        full.host_value = torch.tensor(tuple(full.host_value), dtype=torch.int64)
                node = node.parent
            variants = {
                "baseline": baseline.observe_unified_node_closure,
                "optimized": observer.observe_unified_node_closure,
            }
            costs = {name: {"wall": [], "thread_cpu": []} for name in variants}
            with patch.object(observer.time, "monotonic", new=lambda: 1.):
                expected = asdict(variants["baseline"](cache, leaf))
                if not expected["observable"]:
                    raise ValueError("CPU closure fixture is not observable")
                for iteration in range(105):
                    order = list(variants)
                    if iteration % 2:
                        order.reverse()
                    for name in order:
                        wall, cpu = time.perf_counter_ns(), time.thread_time_ns()
                        result = variants[name](cache, leaf)
                        cpu_us = (time.thread_time_ns() - cpu) / 1000.
                        wall_us = (time.perf_counter_ns() - wall) / 1000.
                        if asdict(result) != expected:
                            raise ValueError("live closure contents or validations changed")
                        if iteration >= 5:
                            costs[name]["wall"].append(wall_us)
                            costs[name]["thread_cpu"].append(cpu_us)
            closure_cases.append({
                "index_type": kind, "mode": mode, "depth": depth,
                "observations_equal": True,
                "output_sha256": hashlib.sha256(json.dumps(expected, sort_keys=True).encode()).hexdigest(),
                "costs": {
                    name: {clock: distribution(values) for clock, values in clocks.items()}
                    for name, clocks in costs.items()
                },
            })
payload = {
    "schema_version": 1, "baseline_revision": REVISION,
    "analysis_started_at_local": started,
    "analysis_finished_at_local": datetime.now().astimezone().isoformat(),
    "baseline_observer_sha256": hashlib.sha256(observer_source.encode()).hexdigest(),
    "optimized_observer_sha256": hashlib.sha256((ROOT / "beliefkv/runtime/sglang_v0520_observer.py").read_bytes()).hexdigest(),
    "optimized_runtime_sha256": hashlib.sha256((ROOT / "beliefkv/runtime/sglang_v0520_runtime.py").read_bytes()).hexdigest(),
    "helper_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    "transfer_prefix": evidence,
    "estimate_cases": estimate_cases, "closure_cases": closure_cases,
    "semantics": [
        "H2D comparison uses fixed recorded bounded histories; this fixture is not the observed frequency of repeated same-size queries.",
        "The baseline is the original exact shape-aware estimator with the original legacy fallback. Both paths use identical histories, sizes and shapes, including unsupported sizes.",
        "Every repeated group includes its first uncached query. Historical input changes and full buffer rotation are validated separately through actual controller callbacks.",
        "Closure comparison uses real CPU int64 index tensors and ordinary ranges; complete live observations match, including reference and pending fields.",
        "Retain range-path regressions. No GPU allocation, CUDA copy, readiness, live policy or throughput/JCT improvement is measured.",
    ],
}
OUTPUT.write_text(json.dumps(payload, indent=2, allow_nan=False) + "\n")
print(json.dumps({
    "estimate_cases": len(estimate_cases),
    "all_estimates_and_closures_equal": True,
    "closure_cpu_reduction_fraction": [
        {key: case[key] for key in ("index_type", "mode", "depth")} | {
            "fraction": 1. - case["costs"]["optimized"]["thread_cpu"]["mean_us"]
            / case["costs"]["baseline"]["thread_cpu"]["mean_us"],
        } for case in closure_cases
    ],
}, indent=2))

"""Separate recorded JOIN trigger work error from later child protocol/rounds."""

from collections import Counter, defaultdict
from datetime import datetime
import gzip
import hashlib
import json
from pathlib import Path
import sys

ROOT = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
SOURCE = ROOT / "experiments/reports/v196_v42_final_wait_prefetch_20261013.json.gz"
OUTPUT = ROOT / "experiments/reports/v204_v42_join_trigger_work_20261013.json"
sys.path.insert(0, str(ROOT))
from scripts.audit_prefetch_lifecycle import distribution, wait_event_identity

if OUTPUT.exists():
    raise ValueError("preserve existing diagnosis")
compressed = SOURCE.read_bytes()
report = json.loads(gzip.decompress(compressed))
seals = report["input_jsonl_prefixes"]
verified = {}


def records(path):
    path = Path(path)
    seal = seals[str(path)]
    consumed, digest = 0, hashlib.sha256()
    with path.open("rb") as stream:
        while consumed < seal["complete_prefix_bytes"]:
            line = stream.readline(seal["complete_prefix_bytes"] - consumed)
            if not line or not line.endswith(b"\n"):
                raise ValueError("source prefix is incomplete")
            consumed += len(line)
            digest.update(line)
            yield line
    if digest.hexdigest() != seal["complete_prefix_sha256"]:
        raise ValueError("sealed input changed")
    verified[str(path)] = seal


opportunity = next(Path(path) for path in seals if path.endswith("/admission_opportunities.jsonl"))
native = opportunity.parent.parent / "server/runtime_events.sglang.jsonl"
starts, issued, offset = defaultdict(list), {}, None
for line in records(opportunity):
    if not any(name in line for name in (
        b'"final_stage_latest_start"', b'"prefetch_native_issued"', b'"safe_point_census"',
    )):
        continue
    row = json.loads(line)
    if row["event"] == "final_stage_latest_start":
        starts[(row["join_id"], row["context_id"], row["context_epoch"])].append(row)
    elif row["event"] == "prefetch_native_issued" and row["source"] == "join_ticket":
        issued[row["command_id"]] = row
    elif row["event"] == "safe_point_census" and offset is None:
        offset = row["ts_ms"] - row["monotonic_ms"]
if offset is None:
    raise ValueError("no recorded clock alignment")
results = {}
for line in records(native):
    if b'"llm_result"' not in line:
        continue
    row = json.loads(line)
    attrs = row.get("attributes") or {}
    if row["kind"] == "llm_result" and type(attrs.get("output_tokens")) is int:
        results[attrs["request_id"]] = row
client_results, terminal_requests = {}, set()
for path in seals:
    if not path.endswith("/runtime_events.deepagents.jsonl"):
        continue
    last_requests = {}
    for line in records(path):
        if b'"llm_result"' not in line and b'"return"' not in line:
            continue
        row = json.loads(line)
        attrs = row.get("attributes") or {}
        if row["kind"] == "llm_result" and not attrs.get("runtime_internal"):
            rid = attrs.get("request_id")
            if rid:
                client_results[rid] = row
                last_requests[row["invocation_id"]] = rid
        elif (
            row["kind"] == "return" and attrs.get("source") == "deepagents_task"
            and attrs.get("outcome") == "completed"
            and row["invocation_id"] in last_requests
        ):
            terminal_requests.add(last_requests[row["invocation_id"]])
actions = defaultdict(list)
for row in report["rows"]:
    if row["source"] == "join_ticket":
        actions[wait_event_identity(row)].append(row)
rows = []
for wait in report["wait_event_attribution"]["rows"]:
    if wait["source"] != "join_ticket" or wait["completion_ts_ms"] is None:
        continue
    full = [
        row for row in actions[wait_event_identity(wait)]
        if (row.get("pool_bytes") or {}).get("kv", 0) > 0 and row["submit_ts_ms"] is not None
    ]
    if not full:
        continue
    action = max(full, key=lambda row: row["submit_ts_ms"])
    issue = issued.get(action["command_id"])
    if issue is None:
        raise ValueError("JOIN physical action lacks issue identity")
    prior = [
        row for row in starts[(issue["join_id"], issue["context_id"], issue["context_epoch"])]
        if row["ts_ms"] <= issue["ts_ms"]
        and row["child_request_id"] == issue.get("child_request_id")
    ]
    trigger = max(prior, key=lambda row: row["ts_ms"]) if prior else None
    result = results.get(issue.get("child_request_id"))
    complete = result["attributes"].get("complete_monotonic_ms") if result else None
    eos = complete + offset if complete is not None else None
    if result is not None and eos is not None and abs(result["ts_ms"] - eos) > 1000.:
        raise ValueError("native completion monotonic/wall evidence disagrees")
    total = result["attributes"]["output_tokens"] if result else None
    actual_work = (
        total - trigger["generated_tokens"]
        if total is not None and trigger is not None else None
    )
    rows.append({
        "join_id": wait["join_id"], "context_id": wait["context_id"],
        "command_id": action["command_id"], "child_request_id": issue.get("child_request_id"),
        "early_full_consumed_bytes": wait["early_started_and_reused_full_bytes"],
        "last_full_submit_lead_to_join_ms": wait["completion_ts_ms"] - action["submit_ts_ms"],
        "full_expirations": wait["full_residency_expirations"],
        "trigger": trigger,
        "trigger_to_native_eos_ms": eos - trigger["ts_ms"] if eos is not None and trigger else None,
        "native_eos_to_join_ms": wait["completion_ts_ms"] - eos if eos is not None else None,
        "actual_generated_remaining_at_trigger": actual_work,
        "projected_work_error_tokens": (
            trigger["projected_remaining_tokens"] - actual_work
            if trigger is not None and actual_work is not None else None
        ),
        "request_natural_child_return": issue.get("child_request_id") in terminal_requests,
        "client_tool_call_count": (
            client_results[issue["child_request_id"]]["attributes"].get("tool_call_count")
            if issue.get("child_request_id") in client_results else None
        ),
    })


def summarize(members):
    return {
        "independent_events": len(members),
        "trigger_kinds": dict(Counter(
            (row["trigger"] or {}).get("trigger_kind", "trigger_missing") for row in members
        )),
        "natural_child_return_requests": sum(row["request_natural_child_return"] for row in members),
        "requests_with_observed_tool_calls": sum(
            bool(row["client_tool_call_count"]) for row in members
        ),
        **{
            name: distribution(row[name] for row in members)
            for name in (
                "last_full_submit_lead_to_join_ms", "trigger_to_native_eos_ms",
                "native_eos_to_join_ms", "actual_generated_remaining_at_trigger",
                "projected_work_error_tokens",
            )
        },
    }


payload = {
    "schema_version": 1, "analyzed_at_local": datetime.now().astimezone().isoformat(),
    "source_report_sha256": hashlib.sha256(compressed).hexdigest(),
    "verified_source_prefixes": verified,
    "clock_offset_wall_minus_monotonic_ms": offset,
    "summary": {
        "early_full_consumed": summarize([row for row in rows if row["early_full_consumed_bytes"]]),
        "no_proven_early_full_consumption": summarize([
            row for row in rows if not row["early_full_consumed_bytes"]
        ]),
    },
    "rows": rows, "helper_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    "semantics": [
        "One last physical FULL submit per completed independent JOIN; demand handoff stays excluded.",
        "Associate a trigger only with the same recorded child request, JOIN, parent context and epoch before issue.",
        "Native EOS uses complete_monotonic_ms plus the recorded clock offset, checked against its already normalized wall ts_ms; do not add the offset twice.",
        "Native EOS and generated token count refer to that request, not a guaranteed natural child RETURN. Natural RETURN uses the sealed client's last model request identity.",
        "EOS-to-JOIN may include later tools, further model rounds, summarization or protocol; do not train all of it as remaining generation.",
        "Negative EOS gaps or work differences are retained. This is diagnostic evidence, not online inputs or causal performance attribution.",
        "No constant correction, new forecast, lease extension or GPU performance improvement is validated here.",
    ],
}
OUTPUT.write_text(json.dumps(payload, indent=2, allow_nan=False) + "\n")
print(json.dumps(payload["summary"], indent=2))

"""Replay causal per-request residual updates on sealed V43 semantic forecasts."""

from collections import defaultdict, deque
from datetime import datetime
import gzip
import hashlib
import json
from math import isfinite
from pathlib import Path
from statistics import mean, median
import sys

ROOT = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
MAIN = Path("/home/longhao/experiment/BeliefKV")
SOURCE = ROOT / "experiments/reports/v206_v43_final_wait_prefetch_20261013.json.gz"
OUTPUT = ROOT / "experiments/reports/v208_v43_causal_work_residual_pilot_20261013.json"
sys.path.insert(0, str(ROOT))
from scripts.audit_prefetch_lifecycle import distribution

if OUTPUT.exists():
    raise ValueError("preserve the previous causal replay")
compressed = SOURCE.read_bytes()
sealed = json.loads(gzip.decompress(compressed))
seals = sealed["input_jsonl_prefixes"]
verified = {}


def lines(path):
    seal = seals[str(path)]
    digest, consumed = hashlib.sha256(), 0
    with Path(path).open("rb") as stream:
        while consumed < seal["complete_prefix_bytes"]:
            line = stream.readline(seal["complete_prefix_bytes"] - consumed)
            if not line or not line.endswith(b"\n"):
                raise ValueError("sealed input truncated")
            consumed += len(line)
            digest.update(line)
            yield line
    if digest.hexdigest() != seal["complete_prefix_sha256"]:
        raise ValueError("sealed input changed")
    verified[str(path)] = seal


opportunity = next(Path(path) for path in seals if path.endswith("/admission_opportunities.jsonl"))
forecasts, offset = [], None
for line in lines(opportunity):
    if b'"semantic_child_forecast"' in line:
        row = json.loads(line)
        if row.get("event") == "semantic_child_forecast":
            forecasts.append(row)
    elif offset is None and b'"safe_point_census"' in line:
        row = json.loads(line)
        if row.get("event") == "safe_point_census":
            offset = row["ts_ms"] - row["monotonic_ms"]
if offset is None:
    raise ValueError("clock evidence absent")
native = {}
for line in lines(opportunity.parent.parent / "server/runtime_events.sglang.jsonl"):
    if b'"llm_result"' not in line:
        continue
    row = json.loads(line)
    attrs = row.get("attributes") or {}
    if row["kind"] == "llm_result" and type(attrs.get("output_tokens")) is int:
        native[attrs["request_id"]] = row
cutoff = datetime.fromisoformat(json.loads(
    (ROOT / "experiments/reports/v206_v43_development_stop_20261013.json").read_bytes()
)["administrative_cutoff_at_local"]).timestamp() * 1000.
returns, tools = {}, set()
for path in seals:
    if not path.endswith("/runtime_events.deepagents.jsonl"):
        continue
    last = {}
    for line in lines(path):
        if b'"llm_result"' not in line and b'"return"' not in line:
            continue
        row = json.loads(line)
        attrs = row.get("attributes") or {}
        if row["kind"] == "llm_result" and not attrs.get("runtime_internal"):
            rid = attrs.get("request_id")
            if rid:
                last[row["invocation_id"]] = rid
                if attrs.get("tool_call_count", 0):
                    tools.add(rid)
        elif (
            row["kind"] == "return" and attrs.get("source") == "deepagents_task"
            and attrs.get("outcome") == "completed" and row["invocation_id"] in last
            and row["ts_ms"] + offset <= cutoff
        ):
            returns[last[row["invocation_id"]]] = row["ts_ms"] + offset
plan = json.loads((opportunity.parent.parent.parent / "ab_plan.json").read_bytes())
artifact = Path(plan["semantic_artifact"])
calibration = json.loads((artifact.parent / "report.json").read_bytes())
threshold = calibration["calibration"]["semantic_event"]["request_operating_point"]["threshold"]


def band(value):
    return next((index for index, bound in enumerate((32., 128., 512.)) if value <= bound), 3)


def project(rid):
    workflow = native[rid]["workflow_id"]
    return workflow.split(":")[2].split("__")[0]


def usable(row):
    return bool(
        row["score"] >= threshold and row["notice_active"]
        and row.get("current_output_tokens", 0) >= 16
        and 0 <= row["observation_age_ms"] <= 1500.
        and row.get("last_service_age_ms") is not None
        and row["last_service_age_ms"] <= 250.
        and row.get("sampled_tokens_per_second")
        and row["sampled_tokens_per_second"] > 0
    )


grouped = defaultdict(list)
for row in sorted(forecasts, key=lambda row: row["ts_ms"]):
    rid = row["request_id"]
    if rid not in native or not usable(row) or row["ts_ms"] >= native[rid]["ts_ms"]:
        continue
    advanced = max(0, row["current_output_tokens"] - row["observed_output_tokens"])
    actual = native[rid]["attributes"]["output_tokens"] - row["current_output_tokens"]
    if actual < 0:
        continue
    center = row["remaining_tokens"] - advanced
    grouped[rid].append({
        "request_id": rid, "ts_ms": row["ts_ms"], "project": project(rid),
        "actual_remaining": actual, "raw_center": center, "band": band(max(0., center)),
        "upper_remaining": row["upper_tokens"] - advanced,
        "tokens_per_second": row["sampled_tokens_per_second"],
        "eos_lead_ms": native[rid]["ts_ms"] - row["ts_ms"],
    })
samples = sorted((row for group in grouped.values() for row in group), key=lambda row: row["ts_ms"])
completed = sorted(
    (timestamp, rid) for rid, timestamp in returns.items() if rid in grouped
)
donors, delivered = defaultdict(lambda: deque(maxlen=64)), 0
replayed = []
for sample in samples:
    while delivered < len(completed) and completed[delivered][0] <= sample["ts_ms"]:
        timestamp, rid = completed[delivered]
        residuals = defaultdict(list)
        for row in grouped[rid]:
            if row["ts_ms"] < timestamp:
                residuals[row["band"]].append(row["actual_remaining"] - row["raw_center"])
        for bucket, values in residuals.items():
            donors[bucket].append((project(rid), median(values), timestamp, rid))
        delivered += 1
    # Exclude the same project as an additional check on transfer across projects.
    available = [
        row for row in donors[sample["band"]] if row[0] != sample["project"]
    ]
    bias = median(row[1] for row in available) if available else 0.
    if any(row[2] > sample["ts_ms"] or row[3] == sample["request_id"] for row in available):
        raise ValueError("future or same-request label leaked into replay")
    replayed.append({
        **sample, "prior_completed_request_donors": len(available),
        "correction_tokens": bias, "corrected_center": sample["raw_center"] + bias,
    })


def error_summary(rows, name):
    values = [max(0., row[name]) - row["actual_remaining"] for row in rows]
    return {
        "independent_requests": len(rows),
        "signed_error_tokens": distribution(values),
        "absolute_error_tokens": distribution(abs(value) for value in values),
        "mean_absolute_error_tokens": mean(map(abs, values)) if values else None,
    }


by_request = defaultdict(list)
for row in replayed:
    by_request[row["request_id"]].append(row)
last = [
    rows[-1] for rid, rows in by_request.items() if rid in returns
]
errors = {}
for bound in (None, 32, 64, 128):
    chosen = [row for row in last if bound is None or row["actual_remaining"] <= bound]
    errors["all" if bound is None else str(bound)] = {
        "baseline": error_summary(chosen, "raw_center"),
        "causal_residual": error_summary(chosen, "corrected_center"),
    }
triggers = []
for horizon in (200., 500., 1000., 2000.):
    for name in ("raw_center", "corrected_center"):
        selected = []
        for rid, rows in by_request.items():
            for row in rows:
                remaining = row[name]
                if remaining <= 0:
                    remaining = row["upper_remaining"]
                if remaining <= 0 or remaining * 1000. / row["tokens_per_second"] > horizon:
                    continue
                selected.append({
                    "request_id": rid, "natural_return": rid in returns,
                    "observed_tool_request": rid in tools, "eos_lead_ms": row["eos_lead_ms"],
                    "causal_donors": row["prior_completed_request_donors"],
                })
                break
        natural = [row for row in selected if row["natural_return"]]
        triggers.append({
            "sampled_horizon_ms": horizon, "variant": name,
            "selected_requests": len(selected), "natural_requests": len(natural),
